from pathlib import Path as _Path
ROOT = _Path(__file__).resolve().parents[1]
"""Regression: a workbook generated by Budget mode must get ZERO Doctor findings - the Doctor runs on our own output and must not
cry wolf. Each workbook is checked twice: as written (never calculated) and as a file saved by Excel (stored results next to every
formula, simulated with the `formulas` package)."""
import io
import sys
import zipfile
from datetime import date

sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(_Path(__file__).resolve().parent))

import pandas as pd
from openpyxl import load_workbook

from budget import autopilot, carryover, categorize, importer, prepare
from budget.model import BudgetConfig
from budget.workbook import build_workbook
from budget_calc import as_saved_by_excel
from budget_fixtures import messy_budget_bytes, personal_style_bytes
from doctor.analyze import analyze
from toolkit.highlight import Annotation, patch_workbook

KM = categorize.default_keyword_map()


def tx(day, description, kind, category, amount, payment="Cash"):
    return {"Date": day, "Description": description, "Type": kind, "Category": category, "Amount": amount, "Payment method": payment}


def blank():
    return build_workbook(BudgetConfig(month_start=date(2026, 6, 1), categories={"Food": 300, "Family / Remittance": 0, "Other": 0}), KM)


def imported():
    raw = importer.read_raw_sheets(messy_budget_bytes())
    name, layout = importer.best_sheet(raw)
    result = importer.import_transactions(raw[name], layout, KM, "PK", date(2026, 6, 1))
    config = BudgetConfig(month_start=date(2026, 6, 1), opening_balance=1000, categories=prepare.starting_categories(KM, result.rows))
    return build_workbook(config, KM, result.rows, result)


def autopilot_template():
    analysis = autopilot.analyze(personal_style_bytes())
    rows, config, _, _ = prepare.finalize(analysis.rows, analysis.config)
    return build_workbook(config, analysis.keyword_map, rows, autopilot.import_info(analysis, analysis.rows))


def busy():
    """Spending in the same category names that also appear as budgets on Settings and as chart labels (the false positive that was seen)."""
    categories = ["Food", "Family / Remittance", "Transport", "Housing", "Other", "Food", "Bills", "Health", "Shopping", "Family / Remittance"]
    rows = pd.DataFrame([tx(date(2026, 6, 2 + i % 20), f"item {i}", "Expense", c, 15 + i) for i, c in enumerate(categories * 3)]
                        + [tx(date(2026, 6, 1), "Salary", "Income", None, 5000), tx(date(2026, 6, 5), "EMI", "Loan payment", None, 300),
                           tx(date(2026, 6, 9), "To savings", "Saving", None, 200), tx(date(2026, 6, 20), "Visa bill", "Card bill payment", None, 100)])
    config = BudgetConfig(month_start=date(2026, 6, 1), opening_balance=1000,
                          categories={"Food": 300, "Family / Remittance": 0, "Transport": 100, "Housing": 2000, "Other": 0, "Bills": 50,
                                      "Health": 50, "Shopping": 0})
    return build_workbook(config, KM, rows)


def next_month():
    first = carryover.read_generated_workbook(busy())
    return build_workbook(carryover.next_month_config(first), first.keyword_map)


WORKBOOKS = {"a blank start": blank, "an import of a messy log": imported, "an upload-and-go import (template style)": autopilot_template,
             "a busy month (category names shared by spending, budgets and chart labels)": busy, "next month, carried over": next_month}

for label, make in WORKBOOKS.items():
    data = make()
    print(f"TEST: Budget mode output gets no findings - {label}")
    report, _ = analyze(data)
    assert report.issues == [], [(i.kind, i.where, i.title) for i in report.issues]
    saved = as_saved_by_excel(data)
    report, _ = analyze(saved)
    assert report.issues == [], [(i.kind, i.where, i.title) for i in report.issues]
    assert load_workbook(io.BytesIO(saved)).sheetnames == load_workbook(io.BytesIO(data)).sheetnames
    print("PASSED")

print("TEST: the three false positives from the first real run are each gone for a specific reason")
report, _ = analyze(busy())
assert not any(i.kind == "label_conflict" for i in report.issues), "a category name shared by spending and a budget is not one figure"
assert not any(i.kind == "inconsistent_formula" for i in report.issues), "a summary row below a table / a chart-table row is not a slip"
print("PASSED")

print("TEST: if something WERE found, the highlighted copy of a Budget workbook keeps all three charts byte-identical")
data = busy()
result = patch_workbook(data, [Annotation("Dashboard", "B5", "high", "a pretend finding")], [], "footer")
before, after = zipfile.ZipFile(io.BytesIO(data)), zipfile.ZipFile(io.BytesIO(result.data))
charts = [n for n in before.namelist() if n.startswith(("xl/charts/", "xl/drawings/"))]
assert len([n for n in charts if n.startswith("xl/charts/chart")]) == 3 and all(before.read(n) == after.read(n) for n in charts)
assert len(load_workbook(io.BytesIO(result.data))["Dashboard"]._charts) == 3
print("PASSED")
